argv:
$ErrorActionPreference='Stop'
$dir='E:\PC-Control\Proxifier-Avito-20261012'
[System.IO.Directory]::CreateDirectory($dir)|Out-Null
$script=@'
$ErrorActionPreference='Stop'
$homeDir=Split-Path -Parent $MyInvocation.MyCommand.Path
$original=Join-Path $env:APPDATA 'Proxifier4\Profiles\Default.ppx'
$backup=Join-Path $homeDir 'Default-original-backup.ppx'
$proposed=Join-Path $homeDir 'SecondChrome-And-AvitoMCP-Direct-PIDs.ppx'
$chromeExe='C:\Program Files\Google\Chrome\Application\chrome.exe'
$proxifierExe='C:\Program Files (x86)\Proxifier\Proxifier.exe'
$chromeProfile='E:\PC-Control\AvitoMCPChrome-20261012\Profile'
$port=17447
if(!(Test-Path $original) -or !(Test-Path $backup) -or !(Test-Path $chromeExe) -or !(Test-Path $proxifierExe)){throw 'PREFLIGHT_FILES_MISSING'}
if((Get-FileHash $original -Algorithm SHA256).Hash -ne (Get-FileHash $backup -Algorithm SHA256).Hash){throw 'PROXIFIER_BASELINE_CHANGED_STOP'}
$chrome=@(Get-CimInstance Win32_Process -Filter "Name='chrome.exe'")
$roots=@($chrome | Where-Object {([string]$_.CommandLine -notmatch '--type=')})
$primary=@($roots | Where-Object {$_.CommandLine -match '--remote-debugging-port=17410'})
$ordinarySecond=@($roots | Where-Object {$_.CommandLine -notmatch '--remote-debugging-port' -and $_.CommandLine -notmatch 'AvitoMCPChrome-20261012'})
if($primary.Count -ne 1 -or $ordinarySecond.Count -ne 1){throw 'CHROME_ROOT_IDENTITY_AMBIGUOUS_ABORT'}
$managed=@($roots|Where-Object {$_.CommandLine -match '--remote-debugging-port=17447' -and $_.CommandLine -match 'AvitoMCPChrome-20261012'})
if($managed.Count -gt 1){throw 'MULTIPLE_MANAGED_CHROME_ROOTS_ABORT'}
$newBrowser=$false
if($managed.Count -eq 0){
 if(@(Get-NetTCPConnection -LocalPort $port -State Listen -ErrorAction SilentlyContinue).Count -gt 0){throw 'PORT_17447_ALREADY_IN_USE_ABORT'}
 [System.IO.Directory]::CreateDirectory((Split-Path $chromeProfile -Parent))|Out-Null
 $arguments=@(
 '--no-first-run','--no-default-browser-check','--no-proxy-server',
 '--remote-debugging-address=127.0.0.1',
 '--remote-debugging-port=17447',
 '--user-data-dir=E:\PC-Control\AvitoMCPChrome-20261012\Profile',
 '--window-size=1440,900',
 'about:blank'
 )
 $p=Start-Process -FilePath $chromeExe -ArgumentList $arguments -PassThru
 $newBrowser=$true
 Start-Sleep -Seconds 3
 $chrome=@(Get-CimInstance Win32_Process -Filter "Name='chrome.exe'")
 $roots=@($chrome | Where-Object {([string]$_.CommandLine -notmatch '--type=')})
 $managed=@($roots | Where-Object {$_.CommandLine -match '--remote-debugging-port=17447' -and $_.CommandLine -match 'AvitoMCPChrome-20261012'})
}
if($managed.Count -ne 1){throw 'MANAGED_BROWSER_NOT_RUNNING_ABORT'}
if($managed[0].ProcessId -eq $primary[0].ProcessId -or $managed[0].ProcessId -eq $ordinarySecond[0].ProcessId){throw 'PROCESS_OVERLAP_ABORT'}
$v=Invoke-RestMethod -Uri 'http://127.0.0.1:17447/json/version' -TimeoutSec 3
if(!$v.Browser){throw 'CDP_UNAVAILABLE_ABORT'}
$targets=@([int]$ordinarySecond[0].ProcessId,[int]$managed[0].ProcessId)
$children=@($chrome | Where-Object {$targets -contains [int]$_.ParentProcessId})
$pids=@($targets+@($children|Select-Object -ExpandProperty ProcessId)|Sort-Object -Unique)
if(([int]$primary[0].ProcessId -in $pids) -or ($pids.Count -lt 2)){throw 'UNSAFE_PID_SCOPE_ABORT'}
$base=[System.IO.File]::ReadAllText($original,[System.Text.Encoding]::UTF8)
$match=[regex]::Match($base,'<RuleList(?:\s[^>]*)?>')
if(!$match.Success -or ([regex]::Matches($base,'<RuleList(?:\s[^>]*)?>').Count -ne 1)){throw 'UNKNOWN_RULE_LIST_ABORT'}
$apps=($pids|ForEach-Object{"pid=$_"} ) -join ';'
$rule=([Environment]::NewLine)+'    <Rule enabled="true">'+([Environment]::NewLine)+'      <Action type="Direct" />'+([Environment]::NewLine)+'      <Applications>'+$apps+'</Applications>'+([Environment]::NewLine)+'      <Name>SecondChrome + AvitoMCP DIRECT [session]</Name>'+([Environment]::NewLine)+'    </Rule>'
$next=$base.Insert($match.Index+$match.Length,$rule)
[xml]$oldXml=$base
[xml]$newXml=$next
$oldRules=@($oldXml.SelectNodes('//*[local-name()="Rule"]/Name')|ForEach-Object {$_.InnerText})
$newRules=@($newXml.SelectNodes('//*[local-name()="Rule"]/Name')|ForEach-Object {$_.InnerText})
if($newRules.Count -ne $oldRules.Count+1 -or $newRules[0] -ne 'SecondChrome + AvitoMCP DIRECT [session]' -or (($newRules|Select-Object -Skip 1) -join '|' -ne ($oldRules -join '|'))){throw 'RULE_ORDER_INVALID_ABORT'}
foreach($tag in @('Options','ProxyList','ChainList')){
 if($oldXml.DocumentElement.SelectSingleNode($tag).OuterXml -cne $newXml.DocumentElement.SelectSingleNode($tag).OuterXml){throw "BASELINE_CHANGED_$tag"}
}
if($next.Replace($rule,'') -cne $base){throw 'EXTRA_CONFIG_DIFF_ABORT'}
[System.IO.File]::WriteAllText($proposed,$next,[System.Text.UTF8Encoding]::new($false))
$load=Start-Process -FilePath $proxifierExe -ArgumentList ('"'+$proposed+'" silent-load') -Wait -PassThru
if($load.ExitCode -ne 0){throw "PROXIFIER_LOAD_FAILED_$($load.ExitCode)"}
$o=[ordered]@{
 result='MCP_AVITO_READY';addedBrowser=$newBrowser;
 mainChromePid=[int]$primary[0].ProcessId;
 existingSecondChromePid=[int]$ordinarySecond[0].ProcessId;
 avitoMcpChromePid=[int]$managed[0].ProcessId;
 avitoMcpCdpPort=17447;procDirectPidCount=$pids.Count;
 mainChromeExcluded=$true;
 originalProxifierRulesUnchanged=$true;
 windowsSystemProxyUnchanged=$true;
 backupPath=$backup
}
$o|ConvertTo-Json -Compress -Depth 4
'@
$path=Join-Path $dir 'START_AVITO_MCP.ps1'
[System.IO.File]::WriteAllText($path,$script,[System.Text.UTF8Encoding]::new($false))
$cmdPath=Join-Path $dir 'START_AVITO_MCP.cmd'
$cmd='@echo off'+[Environment]::NewLine+'powershell.exe -NoProfile -ExecutionPolicy Bypass -File "%~dp0START_AVITO_MCP.ps1"'+[Environment]::NewLine+'echo.'+[Environment]::NewLine+'pause'+[Environment]::NewLine
[System.IO.File]::WriteAllText($cmdPath,$cmd,[System.Text.Encoding]::ASCII)
$tok=$null;$err=$null
[System.Management.Automation.Language.Parser]::ParseFile($path,[ref]$tok,[ref]$err)|Out-Null
if(@($err).Count -gt 0){throw 'SCRIPT_PARSE_FAILED'}
[ordered]@{status='created_not_executed';launcher=$cmdPath;scriptPath=$path;parseErrors=@($err).Count;liveProxyUnchanged=$true}|ConvertTo-Json -Compress
